"use strict";
// timer.lib.civet

import {sprintf} from '@std/fmt/printf'

import {undef} from 'base'
import {integer} from 'datatypes'

const loadTime: integer = Date.now()

// ---------------------------------------------------------------------------

export const sinceLoad = (
		datetime: Date | integer = Date.now()
		): number => {

	if (datetime instanceof Date) {
		return datetime.valueOf() - loadTime
	}
	else {
		return datetime - loadTime
	}
}

// ---------------------------------------------------------------------------

export const sinceLoadStr = (
		datetime: ((Date | integer) | undefined) = undef
		) => {

	return sprintf("%6d", sinceLoad(datetime))
}

// ---------------------------------------------------------------------------

export class CTimer {

	t0 = Date.now()

	// --- automatically resets the timer
	timeTaken(
			reset: boolean = true,
			decPlaces: number = 2,
			divideBy: number = 1
			): string {

		const now = Date.now()
		const secs = (now - this.t0) / 1000
		if (reset) {
			this.t0 = now
		}
		return sprintf(`%.${decPlaces}d`, secs / divideBy)
	}

	timeTakenStr(
			reset: boolean = true,
			decPlaces: number = 2,
			divideBy: number = 1
			): string {

		const now = Date.now()
		const secs = (now - this.t0) / 1000
		if (reset) {
			this.t0 = now
		}
		return sprintf(`%.${decPlaces}d secs.`, secs / divideBy)
	}
}

export const timer = new CTimer()

